content:
Here is the complete, self-contained `galaga.html`. Save it and open it directly in Chrome or Firefox.

```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>GALAGA</title>
<style>
  html,body{margin:0;height:100%;background:#000;overflow:hidden}
  body{display:flex;align-items:center;justify-content:center}
  canvas{background:#000;display:block;image-rendering:pixelated;image-rendering:crisp-edges}
</style>
</head>
<body>
<canvas id="game"></canvas>
<script>
"use strict";
/* ===========================================================================
   GALAGA — a faithful browser clone (single file, no external resources)
   Graphics: pixel-art sprites defined as data + canvas drawing.
   Sound: Web Audio API (synthesized). Loop: fixed timestep via rAF.
   =========================================================================== */

/* ------------------------------- constants -------------------------------- */
const GW=224, GH=288;                 // arcade resolution (3:4)
const FORM_TOP=40, FORM_LEFT=26, CELL_X=17, CELL_Y=15;
const PLAYER_Y=GH-30;
const SHOT_SPEED=3.6, ESHOT_SPEED=1.7, RESPAWN_DELAY=85;

/* ------------------------------- helpers ---------------------------------- */
const clamp=(v,a,b)=>v<a?a:v>b?b:v;
const randInt=n=>Math.floor(Math.random()*n);
function lerp(a,b,t){return a+(b-a)*t;}
function easeOutCubic(t){return 1-Math.pow(1-t,3);}

/* ------------------------------ palette ----------------------------------- */
const PAL={
 '.':null,' ':null,
 B:'#2f6bff', b:'#8fb4ff', W:'#ffffff', w:'#c9d6ff', Y:'#ffe000', y:'#fff59a',
 R:'#ff3b30', r:'#ff8a80', O:'#ff9d00', G:'#2ecc40', g:'#7dff9b', P:'#a15bff',
 p:'#cfa6ff', C:'#22e0ff', c:'#b8f6ff', K:'#0a0a12'
};

/* ------------------------------ sprites ----------------------------------- */
function S(rows,pal){const h=rows.length;return{w:Math.max(...rows.map(r=>r.length)),h,rows,pal:pal||PAL};}

const SPR={
 fighter:S([
  "....W.....",
  "...WW.....",
  "...BB.....",
  "..BBBB....",
  "..BBBBB...",
  ".BBCCBB...",
  ".BBCCBB...",
  "BBCCCCBB..",
  "BBCCCCBB..",
  "YYCWWCY...",
  "Y.CWW.C.Y.",
  "....W....."
 ]),
 fighterRed:S([
  "....R.....","...RR.....","...RR.....","..RRRR....","..RRRRR...",
  ".RRppRR...",".RRppRR...","RRppppRR..","RRppppRR..","YYpWWpY...","Y.pWW.p.Y.","....W....."
 ]),
 fighterGray:S([
  "....w.....","...ww.....","...ww.....","..wwww....","..wwwww...",
  ".wwCCww...",".wwCCww...","wwCCCCww..","wwCCCCww..","YYCWWCY...","Y.CWW.C.Y.","....W....."
 ]),
 zako1:S(["....b.....","...bBb....","...bBb....","..bBBBb...","y.BBBBB.y.",".yyBBBBby.","..yBBBBy..","...BBB....","..B.B.B...","..B.Y.B..."]),
 zako2:S(["....b.....","...bBb....","..ybBBy...",".y.BBBB.y.","yyBBBBBByy",".yBBBBBBy.","..yBBBBy..","...BBB....","..B.B.B...","..B.Y.B..."]),
 goei1:S([".r.....r..","rrR...Rrr.",".rRRRRRr..","..RRRRR...",".wRRRRRw..",".RRRRRRR..","..R.R.R...","..R.R.R..."]),
 goei2:S([".r.....r..","rrR...Rrr.",".rRRRRRr..","..RRRRR...",".wRRRRRw..",".RRRRRRR..","..R.R.R...","..R.R.R..."]),
 boss1:S([
  "....g.g....",
  "...ggggg...",
  "..gGpGg....",
  ".ggGGGgg...",
  "ggGGGGGgg..",
  "ggGGGGGgg..",
  "ggGGGGGgg..",
  ".gGpGpGg...",
  ".gGpGpGg...",
  "..gG.Gg....",
  "..gG.Gg...."
 ]),
 boss2:S([
  "....g.g....","...ggggg...","..gGpGg....",".ggGGGgg...","ggGGGGGgg..",
  "ggGGGGGgg..","ggGGGGGgg..",".gGpGpGg...",".gGpGpGg...","..gG.Gg....","..gG.Gg...."
 ]),
 bossHit1:S([
  "....P.P....","...PPPPP...","..PBbBP....",".PPBBBPP...","PPBBBBBPP..",
  "PPBBBBBPP..","PPBBBBBPP..",".PBbBbBP...",".PBbBbBP...","..PB.BP....","..PB.BP...."
 ]),
 bossHit2:S([
  "....P.P....","...PPPPP...","..PBbBP....",".PPBBBPP...","PPBBBBBPP..",
  "PPBBBBBPP..","PPBBBBBPP..",".PBbBbBP...",".PBbBbBP...","..PB.BP....","..PB.BP...."
 ]),
 bullet:S(["CC","Cc"]),
 eshot1:S(["RR","rR","rr"]),
 eshot2:S(["rr","rR","RR"])
};

/* ------------------------------- audio ------------------------------------ */
const Sound={
 ctx:null,master:null,muted:false,noiseBuf:null,beamOsc:null,beamGain:null,_last:-99999,
 init(){ if(this.ctx)return; try{ this.ctx=new (window.AudioContext||window.webkitAudioContext)(); }catch(e){return;}
   this.master=this.ctx.createGain(); this.master.gain.value=0.5; this.master.connect(this.ctx.destination);
   const n=Math.floor(this.ctx.sampleRate*0.4); const b=this.ctx.createBuffer(1,n,this.ctx.sampleRate); const d=b.getChannelData(0);
   for(let i=0;i<n;i++)d[i]=Math.random()*2-1; this.noiseBuf=b; },
 resume(){ if(this.ctx&&this.ctx.state==='suspended')this.ctx.resume(); },
 now(){return this.ctx?this.ctx.currentTime:0;},
 tone(f,dur,type,vol,slide){ if(!this.ctx||this.muted)return; const t=this.now();
   const o=this.ctx.createOscillator(),g=this.ctx.createGain(); o.type=type||'square';
   o.frequency.setValueAtTime(Math.max(1,f),t); if(slide)o.frequency.exponentialRampToValueAtTime(Math.max(1,slide),t+dur);
   g.gain.setValueAtTime(0.0001,t); g.gain.exponentialRampToValueAtTime(vol||0.2,t+0.005); g.gain.exponentialRampToValueAtTime(0.0001,t+dur);
   o.connect(g).connect(this.master); o.start(t); o.stop(t+dur+0.02); },
 noise(dur,vol,freq,q){ if(!this.ctx||this.muted)return; const t=this.now();
   const s=this.ctx.createBufferSource(); s.buffer=this.noiseBuf; const f=this.ctx.createBiquadFilter(); f.type='bandpass'; f.frequency.value=freq||1000; f.Q.value=q||1;
   const g=this.ctx.createGain(); g.gain.setValueAtTime(vol||0.2,t); g.gain.exponentialRampToValueAtTime(0.0001,t+dur);
   s.connect(f).connect(g).connect(this.master); s.start(t); s.stop(t+dur+0.02); },
 shot(){ if(this.now()-this._last<0.04)return; this._last=this.now(); this.tone(880,0.12,'square',0.15,360); },
 hit(){ this.noise(0.12,0.25,900,1.5); },
 destroy(){ this.noise(0.28,0.4,700,0.7); this.tone(180,0.2,'square',0.12,60); },
 bossHit(){ this.tone(300,0.15,'square',0.25,150); this.noise(0.12,0.2,1400,2); },
 playerExplode(){ this.noise(0.6,0.5,500,0.5); this.tone(300,0.5,'sawtooth',0.25,40); },
 beamStart(){ this.tone(180,0.6,'sine',0.18,900); },
 beamLoop(){ if(!this.ctx||this.muted)return; if(this.beamOsc)return; const t=this.now();
   const o=this.ctx.createOscillator(),g=this.ctx.createGain(); o.type='sawtooth'; o.frequency.value=140;
   g.gain.setValueAtTime(0.0001,t); g.gain.exponentialRampToValueAtTime(0.08,t+0.05); o.connect(g).connect(this.master); o.start(t); this.beamOsc=o; this.beamGain=g; },
 beamStop(){ if(this.beamGain&&this.ctx){ const t=this.now(); try{this.beamGain.gain.cancelScheduledValues(t);this.beamGain.gain.setValueAtTime(Math.max(0.0001,this.beamGain.gain.value),t);this.beamGain.gain.exponentialRampToValueAtTime(0.0001,t+0.1);}catch(e){} }
   const o=this.beamOsc; this.beamOsc=null; if(o)setTimeout(()=>{try{o.stop();}catch(e){}},200); },
 capture(){ this.tone(900,0.5,'square',0.2,180); },
 freed(){ this.tone(400,0.3,'square',0.2,1000); },
 stageStart(){ const n=[660,880,990,1320]; n.forEach((f,i)=>this.tone(f,0.14,'square',0.18)); this.tone(1760,0.25,'square',0.18); },
 bonus(){ const n=[523,659,784,1046]; n.forEach((f,i)=>this.tone(f,0.12,'triangle',0.2)); },
 perfect(){ [523,659,784,1046,1318,1568].forEach((f,i)=>setTimeout(()=>this.tone(f,0.14,'square',0.2),i*70)); }
};

/* --------------------------- formation layout ----------------------------- */
const LAYOUT=[];
for(let c=0;c<4;c++)LAYOUT.push({type:'boss',col:c,row:0});
for(let r=1;r<=2;r++)for(let c=0;c<8;c++)LAYOUT.push({type:'goei',col:c,row:r});
for(let r=3;r<=4;r++)for(let c=0;c<10;c++)LAYOUT.push({type:'zako',col:c,row:r});

function slotPos(e){const cx=FORM_LEFT+e.col*CELL_X+(e.sway||0)+(e.breathX||0);
  return{x:cx-(SPR[e.type].w>>1),y:FORM_TOP+e.row*CELL_Y+(e.breathY||0)};}

function buildFormation(){ G.enemies=[]; for(const s of LAYOUT)G.enemies.push(makeEnemy(s)); }
function makeEnemy(s){const sp=SPR[s.type];return{type:s.type,col:s.col,row:s.row,slot:{col:s.col,row:s.row},
  x:GW/2,y:-24,w:sp.w,h:sp.h,state:'entering',hp:s.type==='boss'?2:1,alive:true,
  path:null,t:0,fireTimer:randInt(90)+60,scored:false,flapPhase:Math.random()*Math.PI*2,
  escorts:[],captured:null,captive:null,hitFlash:0};}

/* --------------------------- entry / dive paths --------------------------- */
function makeEntryPath(sx,sy,ex,ey){const mx=(sx+ex)/2+(Math.random()*40-20);
  const my=sy*0.45+Math.random()*30;return{p0:{x:sx,y:sy},c1:{x:mx,y:my},c2:{x:ex,y:ey},dur:95};}
function bez(p,t){const u=1-t;return{x:u*u*p.p0.x+2*u*t*p.c1.x+t*t*p.c2.x,y:u*u*p.p0.y+2*u*t*p.c1.y+t*t*p.c2.y};}

function makeDivePath(e,tx){const sx=e.x,sy=e.y;let cx,cy;
  if(Math.random()<0.5){cx=sx+(sx<tx?-40:40);cy=GH*0.35;}else{cx=tx;cy=sy+60;}
  return{p0:{x:sx,y:sy},c1:{x:cx,y:cy},c2:{x:tx,y:GH+30},dur:140};}

function makeReturnPath(e){const p=slotPos(e);return{p0:{x:e.x,y:-16},c1:{x:e.x+(Math.random()*20-10),y:FORM_TOP-8},c2:p,dur:55};}

/* --------------------------- challenging stage ---------------------------- */
function makeLoopPath(sx,sy){const cx=GW/2,cy=GH*0.34,rx=Math.min(96,GW/2-14),ry=36;
  const a0=Math.atan2(sy-cy,sx-cx);return{cx,cy,rx,ry,a0,dur:210};}
function loopPos(p,t){const a=p.a0+t*Math.PI*2;return{x:p.cx+Math.cos(a)*p.rx,y:p.cy+Math.sin(a)*p.ry};}

/* ------------------------------- game state ------------------------------- */
const G={state:'title',frame:0,stage:1,score:0,high:0,nextExtra:20000,lives:3,
  enemies:[],shots:[],eshots:[],explosions:[],player:null,capturedFighter:null,dual:false,
  fireTimer:60,formation:{swayT:0,breathT:0},stageState:'normal',
  entryGroups:[],entryIndex:0,entryTimer:0,
  chStage:{wave:0,waveEnemies:[],spawned:false},chHits:0,chBonus:0,perfect:false,
  stageTextT:0,readyT:0,respawnDelay:0,gameOverT:0,titleT:0,hitStats:{fired:0,hits:0},muteFlash:0};

function loadHigh(){try{const v=localStorage.getItem('galaga_high');if(v)G.high=parseInt(v)||0;}catch(e){}}
function saveHigh(){try{localStorage.setItem('galaga_high',String(G.high));}catch(e){}}

/* ------------------------------- input ------------------------------------ */
const keys={left:false,right:false,fire:false};
addEventListener('keydown',e=>{
  Sound.init();Sound.resume();
  const k=e.key;
  if(k==='ArrowLeft'||k==='a'||k==='A'){keys.left=true;}
  if(k==='ArrowRight'||k==='d'||k==='D'){keys.right=true;}
  if(k===' '){keys.fire=true;}
  if(k==='Enter')onEnter();
  if(k==='p'||k==='P')togglePause();
  if(k==='m'||k==='M'){Sound.muted=!Sound.muted;G.muteFlash=40;}
  if(['ArrowLeft','ArrowRight',' ','ArrowUp','ArrowDown'].includes(k))e.preventDefault();
});
addEventListener('keyup',e=>{const k=e.key;
  if(k==='ArrowLeft'||k==='a'||k==='A')keys.left=false;
  if(k==='ArrowRight'||k==='d'||k==='D')keys.right=false;
  if(k===' ')keys.fire=false;});

function onEnter(){Sound.init();Sound.resume();if(G.paused)return;
  if(G.state==='title')startGame();else if(G.state==='gameover'){G.state='title';G.titleT=0;}}
function togglePause(){if(G.state==='playing')G.paused=!G.paused;}

/* ------------------------------ game flow --------------------------------- */
function startGame(){Sound.stageStart();G.score=0;G.lives=3;G.nextExtra=20000;G.stage=1;
  G.shots=[];G.eshots=[];G.explosions=[];G.capturedFighter=null;G.dual=false;
  G.hitStats={fired:0,hits:0};startStage();}

function startStage(){Sound.stageStart();G.state='playing';G.paused=false;G.stageTextT=110;
  G.shots=[];G.eshots=[];G.explosions=[];G.fireTimer=60;G.capturedFighter=null;G.dual=false;
  G.chStage={wave:0,waveEnemies:[],spawned:false};G.chHits=0;G.chBonus=0;G.perfect=false;
  G.player=makePlayer();G.respawnDelay=0;G.readyT=30;
  buildFormation();G.stageState=isChallenging(G.stage)?'challenging':'normal';
  G.formation.swayT=0;G.formation.breathT=0;
  if(G.stageState==='normal')setupEntryGroups();}

function isChallenging(s){return s>=3&&(s-3)%4===0;}
function setupEntryGroups(){G.entryGroups=[];const rows=[[],[],[],[],[]];
  for(const e of G.enemies)rows[e.row].push(e);
  const order=[rows[0],rows[1],rows[2],rows[3],rows[4]];
  for(let i=0;i<order.length;i++){order[i].sort((a,b)=>a.col-b.col);const g=order[i];g.forEach(e=>e.state='waiting');}
  G.entryGroups=order;G.entryIndex=0;G.entryTimer=10;}

function launchGroup(gi){const group=G.entryGroups[gi];if(!group||!group.length)return;
  const n=group.length;for(let i=0;i<n;i++){const e=group[i];e.state='entering';
    const fromLeft=(gi%2===0)?(i%2===0):(i%2===1);
    let sx=fromLeft?-24:GW+24,sy=-30;
    if(i===n-1)sx=fromLeft?GW/2:-24;
    e.path=makeEntryPath(sx,sy,slotPos(e).x,slotPos(e).y);e.t=0;}
  G.entryIndex++;G.entryTimer=58;}

function spawnChWave(){const n=8,arr=[];for(let i=0;i<n;i++){const type=i<2?'boss':(i<4?'goei':'zako');
  const e=makeEnemy({type,col:i,row:0});e.state='chfly';e.scored=false;arr.push(e);G.enemies.push(e);}
  G.chStage.waveEnemies=arr;}

function makePlayer(){const w=G.dual?24:12;return{x:GW/2,y:PLAYER_Y,w,h:12,alive:true,respawnT:0};}
function playerHalfX(half){if(!G.dual)return G.player.x;return half===0?G.player.x-6:G.player.x+6;}

/* --------------------------- scoring / lives -------------------------------- */
function addScore(p){G.score+=p;if(G.score>G.high)G.high=G.score;while(G.score>=G.nextExtra){G.lives++;G.nextExtra+=70000;}}
function loseLife(){Sound.beamStop();if(G.dual){G.dual=false;return;}
  G.lives--;if(G.lives<=0){gameOver();return;}G.respawnDelay=RESPAWN_DELAY;}
function gameOver(){G.state='gameover';G.gameOverT=0;saveHigh();}

/* ------------------------------ collisions -------------------------------- */
function hit(ax,ay,aw,ah,bx,by,bw,bh){return ax<bx+bw&&ax+aw>bx&&ay<by+bh&&ay+ah>by;}
function pointInTri(px,py,ax,ay,bx,by,cx,cy){const d1=(px-bx)*(ay-by)-(ax-bx)*(py-by);
  const d2=(px-cx)*(by-cy)-(bx-cx)*(py-cy);const d3=(px-ax)*(cy-ay)-(cx-ax)*(py-ay);
  const neg=(d1<0)||(d2<0)||(d3<0),pos=(d1>0)||(d2>0)||(d3>0);return!(neg&&pos);}

/* ------------------------------ shooting ---------------------------------- */
function fire(){if(!G.player||!G.player.alive)return;
  if(G.shots.length>=(G.dual?2:1))return;Sound.shot();G.hitStats.fired++;
  const xs=G.dual?[playerHalfX(0),playerHalfX(1)]:[G.player.x];
  for(const x of xs)G.shots.push({x,y:PLAYER_Y-8});}

function shootPlayer(e){if(!G.player||!G.player.alive)return;Sound.eshot();
  G.eshots.push({x:e.x+e.w/2,y:e.y+e.h,vx:(Math.random()*0.6-0.3),vy:ESHOT_SPEED});}

/* ------------------------------ explosions -------------------------------- */
function boom(x,y,small){G.explosions.push({x,y,t:0,life:small?14:22,small:!!small});}

/* ================================ UPDATE ================================== */
function update(){G.frame++;if(G.muteFlash>0)G.muteFlash--;
  if(G.state==='title'){updateTitle();return;}
  if(G.state==='gameover'){G.gameOverT++;return;}
  if(G.paused)return;
  updateStars();
  G.formation.swayT+=0.02;
  const complete=G.enemies.every(e=>e.state!=='entering'&&e.state!=='waiting');
  G.formation.breathT=complete?G.formation.breathT+0.018:0;
  updatePlayer();updateShots();updateEshots();updateEnemies();updateCapturedFighter();updateExplosions();checkWin();}

function updateStars(){for(const s of G.stars){s.y+=s.spd;if(s.y>GH){s.y-=GH;s.x=Math.random()*GW;}}}

function updateTitle(){G.titleT++;if(G.titleT%40===0)G.high=G.score;}

function updatePlayer(){const p=G.player;if(!p)return;
  if(p.respawnT>0){p.respawnT--;if(p.respawnT<=0)p.alive=true;return;}
  const sp=1.6;if(keys.left)p.x-=sp;if(keys.right)p.x+=sp;
  p.x=clamp(p.x,(G.dual?12:6),GW-(G.dual?12:6));}

function updateShots(){for(const s of G.shots)s.y-=SHOT_SPEED;
  for(let i=G.shots.length-1;i>=0;i--){const s=G.shots[i];if(s.y<-8){G.shots.splice(i,1);continue;}
    let hit=false;
    for(const e of G.enemies){if(!e.alive||e.state==='waiting')continue;if(e.hitFlash>0)continue;
      if(hit(s.x-2,s.y-4,4,8,e.x,e.y,e.w,e.h)){hitEnemy(e);G.shots.splice(i,1);hit=true;break;}}
    if(hit)continue;
    const cf=G.capturedFighter;if(cf&&cf.state==='freeing'&&cf.freeT<30){if(hit(s.x-2,s.y-4,4,8,cf.x-6,cf.y-5,12,12)){G.shots.splice(i,1);}}
  }
  G.shots=G.shots.filter(s=>s.y>-8);}

function updateEshots(){for(const s of G.eshots){s.x+=s.vx||0;s.y+=s.vy;}
  for(let i=G.eshots.length-1;i>=0;i--){const s=G.eshots[i];if(s.y>GH+6||s.y<-8||s.x<-8||s.x>GW+8){G.eshots.splice(i,1);continue;}
    if(G.player&&G.player.alive&&pHitTest(s.x-2,s.y-3,4,6)){hitPlayer();G.eshots.splice(i,1);}}}

function pHitTest(x,y,w,h){if(!G.player||!G.player.alive)return false;const p=G.player;
  if(G.dual){return hit(x,y,w,h,p.x-12,p.y-5,11,10)||hit(x,y,w,h,p.x+1,p.y-5,11,10);}
  return hit(x,y,w,h,p.x-5,p.y-4,10,9);}

function updateEnemies(){for(const e of G.enemies){if(!e.alive)continue;if(e.hitFlash>0)e.hitFlash--;
  if(e.state==='entering'){e.t++;const p=bez(e.path,e.t/e.path.dur);e.x=p.x;e.y=p.y;
    if(e.t>=e.path.dur){e.state='formation';}}
  else if(e.state==='dive'||e.state==='returning'||e.state==='beam'){
    if(!e.path){const p=slotPos(e);e.x=p.x;e.y=p.y;}else{e.t++;const p=bez(e.path,e.t/e.path.dur);e.x=p.x;e.y=p.y;}}
  else if(e.state==='chfly'){e.t++;const p=loopPos(e.path,e.t/e.path.dur);e.x=p.x;e.y=p.y;}
  else{const p=slotPos(e);e.x=p.x;e.y=p.y;}
  }
  // dive scheduling (normal stages)
  if(G.stageState==='normal'&&G.enemies.some(e=>e.state==='formation')&&(!G.player||G.player.alive)&&G.respawnDelay<=0){
    G.fireTimer--;if(G.fireTimer<=0){scheduleDive();G.fireTimer=clamp(150-G.stage*8,32,150);}}
  // per-enemy behaviour
  for(const e of G.enemies){if(!e.alive)continue;
    if(e.state==='formation'){if(Math.random()<0.0009&&G.respawnDelay<=0&&(G.player?G.player.alive:true))shootPlayer(e);}
    else if(e.state==='dive'||e.state==='beam'){if(G.respawnDelay<=0){const r=e.type==='boss'?0.01:0.02;if(Math.random()<r)shootPlayer(e);}}
  }
  // beam capture + captive fire
  const beamer=G.enemies.find(e=>e.alive&&e.state==='beam');
  if(beamer){Sound.beamLoop();updateBeamCapture(beamer);}else Sound.beamStop();
  if(G.capturedFighter&&G.capturedFighter.state==='held'){const boss=G.capturedFighter.boss;
    if(boss&&(boss.state==='dive'||boss.state==='beam')&&G.respawnDelay<=0){if(Math.random()<0.01)shootPlayer(boss);}}
  // challenging stage flow
  if(G.stageState==='challenging')updateChallenging();}

function scheduleDive(){const form=G.enemies.filter(e=>e.alive&&e.state==='formation');if(!form.length)return;
  const bosses=form.filter(e=>e.type==='boss');let e,boss=null,escorts=[];
  if(bosses.length&&Math.random()<0.5){boss=bosses[randInt(bosses.length)];e=boss;}else{e=form[randInt(form.length)];}
  startDive(e);if(boss){const goei=G.enemies.filter(x=>x.alive&&x.state==='formation'&&x.type==='goei');
    const cnt=Math.random()<0.5?2:(Math.random()<0.6?1:0);for(let i=0;i<cnt&&goei.length;i++){const g=goei.splice(randInt(goei.length),1)[0];g.state='dive';g.path=makeDivePath(g,boss.x+e.w/2+(i===0?-14:14));boss.escorts.push(g);}}}

function startDive(e){const tx=G.player&&G.player.alive?clamp(G.player.x,24,GW-24):GW/2;
  e.state='dive';e.path=makeDivePath(e,tx);e.t=0;}

function updateBeamCapture(boss){if(!boss.captive)boss.captive={state:'approach',t:0};const c=boss.captive;
  if(c.state==='approach'){c.t++;const p=bez(c.path,c.t/c.path.dur);c.x=p.x;c.y=p.y;if(c.t>=c.path.dur)c.state='beam';}
  else{c.beamT=(c.beamT||0)+1;
    if(!G.capturedFighter&&G.player&&G.player.alive){const bx=boss.x+boss.w/2,by=boss.y+boss.h;
      const halfW=4+c.beamT*0.25;if(c.beamT>6&&c.beamT<130&&Math.abs(G.player.x-bx)<halfW&&G.player.y>=by){capture(boss);}}}}

function capture(boss){Sound.capture();Sound.beamStop();
  G.capturedFighter={boss,x:boss.x+boss.w/2,y:PLAYER_Y,state:'capturing',t:0,freeT:0};
  boom(G.player.x,G.player.y,false);G.dual=false;loseLife();}

function updateCapturedFighter(){const cf=G.capturedFighter;if(!cf)return;const boss=cf.boss;
  if(cf.state==='capturing'){cf.t++;cf.y+=(boss.y+18-cf.y)*0.25;cf.x=boss.x+boss.w/2;
    if(cf.t>30){cf.state='held';if(boss)boss.captured=cf;}}
  else if(cf.state==='held'){if(!boss||!boss.alive){G.capturedFighter=null;return;}cf.x=boss.x+boss.w/2;cf.y=boss.y+18;}
  else if(cf.state==='freeing'){cf.freeT++;cf.y+=0.9;if(G.player&&G.player.alive&&Math.abs(cf.x-G.player.x)<14&&cf.y>G.player.y-6){
      G.dual=true;Sound.freed();G.capturedFighter=null;}}}

function updateChallenging(){const cs=G.chStage;
  if(cs.wave>=5){G.state='stageend';G.stageTextT=0;if(G.perfect)Sound.perfect();else Sound.bonus();return;}
  const alive=cs.waveEnemies.filter(e=>e.alive).length;
  if(!alive&&cs.spawned){const bonus=8*100;addScore(bonus);G.chBonus+=bonus;cs.wave++;cs.spawned=false;cs.waveEnemies=[];return;}
  if(!cs.spawned&&!cs.waveEnemies.length)spawnChWave();
  if(cs.spawned&&alive===0){cs.spawned=false;}
  if(!cs.spawned&&cs.wave<5){cs.spawned=true;cs.waveEnemies.forEach((e,i)=>{const sx=GW/2+(i-3.5)*18,sy=-20-i*4;
    e.state='chfly';e.path=makeLoopPath(sx,sy);e.t=i*6;});}}

function updateExplosions(){for(const x of G.explosions)x.t++;G.explosions=G.explosions.filter(x=>x.t<x.life);}

function checkWin(){if(G.stageState==='normal'){const alive=G.enemies.some(e=>e.alive);
  if(!alive){G.state='stageend';G.stageTextT=0;Sound.bonus();}}}

/* ------------------------------ combat events ----------------------------- */
function hitEnemy(e){const cx=e.x+e.w/2,cy=e.y+e.h/2;
  if(e.type==='boss'){if(e.hp>1){e.hp--;e.hitFlash=8;addScore(50);Sound.bossHit();boom(cx,cy,true);}else{destroyEnemy(e);}}
  else destroyEnemy(e);}

function destroyEnemy(e){const cx=e.x+e.w/2,cy=e.y+e.h/2;e.alive=false;G.hitStats.hits++;
  if(G.stageState==='challenging'){addScore(100);G.chHits++;boom(cx,cy,false);Sound.destroy();return;}
  const diving=e.state==='dive'||e.state==='beam';let pts=0;
  if(e.type==='zako')pts=diving?100:50;else if(e.type==='goei')pts=diving?160:80;
  else{if(diving){const n=e.escorts.filter(x=>x.alive).length;pts=n===2?1600:n===1?800:400;}else pts=150;}
  addScore(pts);boom(cx,cy,false);Sound.destroy();
  if(e.type==='boss'){if(e.captive){e.captive=null;}
    if(G.capturedFighter&&G.capturedFighter.boss===e){const cf=G.capturedFighter;cf.state='freeing';cf.freeT=0;Sound.freed();}}
  if(e.escorts)for(const g of e.escorts)if(g.alive&&!g.dying){g.dying=true;g.path=null;}
  for(const o of G.enemies)if(o!==e&&o.escorts&&o.escorts.includes(e))o.escorts=o.escorts.filter(x=>x!==e);}

function hitPlayer(){if(!G.player||!G.player.alive)return;Sound.playerExplode();boom(G.player.x,G.player.y,false);
  if(G.dual){G.dual=false;G.player.respawnT=36;return;}
  loseLife();if(G.state==='playing'){G.player.alive=false;G.player.respawnT=RESPAWN_DELAY;}}

/* ------------------------------ stage end --------------------------------- */
function advanceStage(){G.stage++;startStage();}

/* ================================ RENDER ================================== */
const canvas=document.getElementById('game');const ctx=canvas.getContext('2d');
let scale=1;function resize(){scale=Math.max(1,Math.floor(Math.min(window.innerWidth/GW,window.innerHeight/GH)));
  canvas.width=GW*scale;canvas.height=GH*scale;ctx.imageSmoothingEnabled=false;}
addEventListener('resize',resize);

function drawSprite(sp,x,y,flash){const px=Math.round(x),py=Math.round(y);const rows=sp.rows,pal=sp.pal;
  for(let r=0;r<sp.h;r++){const row=rows[r];for(let c=0;c<row.length;c++){let col=pal[row[c]];if(!col)continue;
    if(flash&&r%2===1)col='#ffffff';ctx.fillStyle=col;ctx.fillRect(px+c,py+r,1,1);}}}

function drawPlayer(){const p=G.player;if(!p)return;if(p.respawnT>0&&Math.floor(G.frame/4)%2===0)return;
  const sp=G.dual?SPR.fighterGray:SPR.fighter;
  if(G.dual){drawSprite(sp,p.x-12,p.y-5);drawSprite(sp,p.x+1,p.y-5);}else drawSprite(sp,p.x-6,p.y-5);}

function drawEnemy(e){if(!e.alive)return;let sp;
  if(e.type==='zako')sp=(Math.floor(G.frame/8)+e.flapPhase|0)%2?SPR.zako2:SPR.zako1;
  else if(e.type==='goei')sp=Math.floor(G.frame/7)%2?SPR.goei2:SPR.goei1;
  else{if(e.hp===1)sp=(Math.floor(G.frame/8)+e.flapPhase|0)%2?SPR.bossHit2:SPR.bossHit1;else sp=Math.floor(G.frame/8)%2?SPR.boss2:SPR.boss1;}
  drawSprite(sp,e.x,e.y,e.hitFlash>0);}

function drawBeam(boss){const bx=boss.x+boss.w/2,by=boss.y+boss.h,cy=GH-6,halfW=4+(boss.captive.beamT||0)*0.25;
  const g=ctx.createLinearGradient(0,by,0,cy);g.addColorStop(0,'rgba(120,190,255,0.85)');g.addColorStop(1,'rgba(40,90,220,0.15)');
  ctx.fillStyle=g;ctx.beginPath();ctx.moveTo(bx-3,by);ctx.lineTo(bx+3,by);ctx.lineTo(bx+halfW,cy);ctx.lineTo(bx-halfW,cy);ctx.closePath();ctx.fill();
  const off=(G.frame%24)/24;for(let i=0;i<5;i++){const t=((i/5)+off)%1,y=by+(cy-by)*t,w=3+halfW*t*0.9;
    ctx.fillStyle='rgba(200,235,255,'+(0.6*(1-t))+')';ctx.fillRect(bx-w,y,w*2,2);}}

function drawCapturedFighter(){const cf=G.capturedFighter;if(!cf)return;drawSprite(SPR.fighterRed,cf.x-6,cf.y-5);}

function drawShots(){for(const s of G.shots)drawSprite(SPR.bullet,s.x-1,s.y-4);
  for(const s of G.eshots)drawSprite(Math.floor(G.frame/3)%2?SPR.eshot2:SPR.eshot1,s.x-1,s.y-3);}

function drawExplosions(){for(const x of G.explosions){const t=x.t/x.life,r=2+t*(x.small?7:14);
  const col=t<0.5?'#fff':t<0.75?'#ff8a00':'#c00';ctx.fillStyle=col;
  ctx.beginPath();ctx.arc(x.x,x.y,r,0,Math.PI*2);ctx.fill();
  if(t>0.3){ctx.fillStyle='#ffdf6b';ctx.beginPath();ctx.arc(x.x,x.y,r*0.5,0,Math.PI*2);ctx.fill();}}}

function drawStars(){for(const s of G.stars){const tw=0.5+0.5*Math.sin(G.frame*s.tw+s.ph);
  ctx.fillStyle='rgba('+s.col+','+(0.35+0.65*tw)+')';ctx.fillRect(Math.round(s.x),Math.round(s.y),1,1);}}

function drawHUD(){ctx.textAlign='left';ctx.font='bold 7px "Courier New",monospace';
  ctx.fillStyle='#ff2b2b';ctx.fillText('1UP',6,9);
  ctx.fillStyle=Math.floor(G.frame/30)%2?'#ff2b2b':'#8a0000';ctx.fillText(String(G.score).padStart(6,' '),6,17);
  ctx.textAlign='center';ctx.fillStyle='#ffffff';ctx.fillText('HIGH SCORE',GW/2,9);
  ctx.fillStyle='#ffe000';ctx.fillText(String(Math.max(G.high,G.score)).padStart(6,' '),GW/2,17);
  // reserve ships (bottom-left)
  for(let i=0;i<G.lives-1;i++)drawSprite(SPR.fighter,4+i*13,GH-12);
  // stage badges (bottom-right)
  let x=GW-6;const denom=[50,30,20,10,5,1];let n=G.stage;
  for(const d of denom){while(n>=d&&x>4){n-=d;drawBadge(x,GH-8,d);x-=11;}}
  if(G.muteFlash>0){ctx.textAlign='right';ctx.fillStyle='#22e0ff';ctx.fillText('MUTE',GW-6,9);}
}
function drawBadge(cx,cy,val){const c=val>=30?'#ff2b2b':val>=20?'#ff9d00':val>=10?'#ffe000':'#4dff4d';
  ctx.fillStyle=c;ctx.fillRect(cx-5,cy-5,10,10);ctx.strokeStyle='#0a0a12';ctx.lineWidth=1;ctx.strokeRect(cx-4.5,cy-4.5,9,9);
  ctx.fillStyle='#0a0a12';ctx.font='bold 6px "Courier New",monospace';ctx.textAlign='center';ctx.fillText(String(val),cx,cy+2);}

function centerText(t,y,col,size){ctx.textAlign='center';ctx.font='bold '+(size||7)+'px "Courier New",monospace';
  ctx.fillStyle=col;ctx.fillText(t,GW/2,y);}

function drawTitle(){centerText('GALAGA',60,'#ff4d4d',30);centerText('* * *',80,'#ffe000',10);
  centerText('PRESS ENTER TO START',100,Math.floor(G.frame/25)%2?'#ffffff':'#8a8aff',9);
  const rows=[['ZAKO','50 / 100','#4da6ff'],['GOEI','80 / 160','#ff4d4d'],['BOSS GALAGA','150 / 400 - 1600','#2ecc40']];
  ctx.textAlign='left';ctx.font='bold 7px "Courier New",monospace';let y=130;
  for(const r of rows){drawSprite(SPR[r[0].toLowerCase().split(' ')[0]==='boss'?'boss':'zako'],40,y-6);
    ctx.fillStyle=r[2];ctx.fillText(r[0],58,y);ctx.textAlign='right';ctx.fillStyle='#ffffff';ctx.fillText(r[1],GW-30,y);ctx.textAlign='left';y+=20;}
  centerText('CHALLENGING STAGE   100 PTS',214,'#ffe000',7);
  centerText('EXTRA SHIP EVERY 70,000 PTS',228,'#ffffff',6);
  ctx.textAlign='right';ctx.fillStyle='#ff2b2b';ctx.fillText('HIGH SCORE '+Math.max(G.high,G.score),GW-6,250);
  centerText('ARROWS/AD MOVE   SPACE FIRE   ENTER START',262,'#8a8aff',6);
  centerText('P PAUSE   M MUTE',274,'#8a8aff',6);}

function drawStageEnd(){const cs=G.chStage;centerText('STAGE '+G.stage,GH*0.3,'#ffffff',12);
  if(G.stageState==='challenging'){centerText('CHALLENGING STAGE',GH*0.3+16,'#ffe000',8);
    centerText('NUMBER OF HITS: '+G.chHits,GH*0.45,'#ffffff',9);
    centerText('BONUS: '+G.chBonus,GH*0.52,'#4dff4d',9);
    if(G.perfect)centerText('PERFECT! 10,000',GH*0.6,Math.floor(G.frame/8)%2?'#ff2b2b':'#ffe000',10);}
  else centerText('STAGE CLEARED!',GH*0.45,'#4dff4d',10);}

function render(){ctx.fillStyle='#000';ctx.fillRect(0,0,GW,GH);
  ctx.save();ctx.scale(scale,scale);drawStars();
  if(G.state==='title'){drawTitle();ctx.restore();return;}
  // enemies & beam & captive
  const beamer=G.enemies.find(e=>e.alive&&e.state==='beam');if(beamer)drawBeam(beamer);
  for(const e of G.enemies)drawEnemy(e);
  drawCapturedFighter();drawShots();drawPlayer();drawExplosions();drawHUD();
  if(G.stageTextT>0){G.stageTextT--;centerText('STAGE '+G.stage,GH*0.45,Math.floor(G.frame/8)%2?'#ffffff':'#ffe000',16);}
  else if(G.readyT>0){G.readyT--;centerText('READY',GH*0.5,'#ff2b2b',14);}
  if(G.paused)centerText('PAUSED',GH*0.5,'#ffffff',14);
  if(G.state==='gameover'){ctx.fillStyle='rgba(0,0,0,0.6)';ctx.fillRect(0,GH*0.3,GW,90);
    centerText('GAME OVER',GH*0.4,'#ff2b2b',16);
    const hs=G.hitStats;const ratio=hs.fired?Math.round(hs.hits/hs.fired*100):0;
    centerText('SHOTS FIRED: '+hs.fired,GH*0.5,'#ffffff',8);
    centerText('HITS: '+hs.hits,GH*0.56,'#ffffff',8);
    centerText('HIT-MISS RATIO: '+ratio+'%',GH*0.62,'#ffe000',8);
    if(G.gameOverT>90&&Math.floor(G.frame/25)%2)centerText('PRESS ENTER',GH*0.72,'#8a8aff',8);}
  ctx.restore();}

/* ------------------------------ main loop --------------------------------- */
function updateStageEnd(){G.stageTextT++;const dur=G.stageState==='challenging'?230:150;
  if(G.stageTextT>=dur){if(G.stageState==='challenging'&&G.chHits>=40&&!G.perfect){G.perfect=true;addScore(10000);}advanceStage();}}

let last=performance.now(),acc=0;const STEP=1000/60;
function loop(now){requestAnimationFrame(loop);let dt=now-last;last=now;if(dt>250)dt=250;acc+=dt;
  while(acc>=STEP){if(G.state==='stageend')updateStageEnd();else update();acc-=STEP;}render();}

/* -------------------------------- boot ------------------------------------ */
function initStars(){G.stars=[];const cols=['255,255,255','160,190,255','255,230,180','180,255,220'];
  for(let i=0;i<70;i++)G.stars.push({x:Math.random()*GW,y:Math.random()*GH,spd:0.1+Math.random()*0.9,
    col:cols[randInt(cols.length)],ph:Math.random()*6.28,tw:0.05+Math.random()*0.1});}

loadHigh();initStars();resize();requestAnimationFrame(loop);
</script>
